def is_palindrome(x):
    s = str(x)
    return s == s[::-1]

def plus_one(digits):
    for i in range(len(digits)-1, -1, -1):
        if digits[i] < 9:
            digits[i] += 1
            return digits
        digits[i] = 0
    return [1] + digits

def trailing_zeroes(n):
    cnt = 0
    while n:
        n //= 5
        cnt += n
    return cnt

def my_sqrt(x):
    g = x
    while g > x // g:
        g = (g + x // g) // 2
    return g

from math import isqrt
def my_sqrt(x):
    return isqrt(x)

def my_pow(x, n):
    if n == 0: return 1.0
    if n < 0: return 1 / my_pow(x, -n)
    if n % 2:
        return x * my_pow(x*x, (n-1)//2)
    return my_pow(x*x, n//2)
